<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, ref, watch } from 'vue'
import { ArrowUp, ArrowUpRight, Plus, Search, PanelLeftClose, PanelLeftOpen, Sparkles, ChevronDown, Code2, Eye, Monitor, Smartphone, RotateCcw, Download, History, X, Check, LoaderCircle, CircleAlert, Play, Square, FolderOpen, ArrowLeft, Copy, Globe, Settings2, Command, MessageSquare, FileCode2, CheckCheck, Image as ImageIcon } from 'lucide-vue-next'
import { api, type Project, type Detail, type Files, type Run, type Version, type Mode, type ModelConfig } from './api'
import { canPreview, previewDocument } from './preview'
import ModeControls from './ModeControls.vue'
import { randomId } from './randomId'
const projects = ref<Project[]>([]), project = ref<Detail | null>(null)
const config = ref<ModelConfig>({ demo:true, model:'', configured:false, models:{build:[],chat:[],image:[]}, defaults:{build:'',chat:'',image:''} }), connected = ref(false)
const mode=ref<Mode>('build'), selectedModel=ref('')
const modeLabels:Record<Mode,string>={build:'构建应用',chat:'对话问答',image:'图像生成'}
const placeholder=computed(()=>mode.value==='chat'?'直接提问，或一起讨论你的需求…':mode.value==='image'?'描述画面内容、风格、构图和色彩…':'告诉 Atoms 团队你的想法，剩下的交给我们…')
const generatedImages=computed(()=>project.value?.messages.filter(m=>m.imageUrl)||[])
function selectModel(value:string){selectedModel.value=value;localStorage.setItem('atoms-model-'+mode.value,value)}
function selectMode(value:Mode){mode.value=value;localStorage.setItem('atoms-mode',value);const saved=localStorage.getItem('atoms-model-'+value);selectedModel.value=saved&&config.value.models[value].includes(saved)?saved:config.value.defaults[value];if(value==='image'&&project.value)view.value='images';else if(view.value==='images')view.value='preview'}
const prompt = ref(''), search = ref(''), sidebar = ref(window.innerWidth > 850), view = ref<'preview'|'code'|'images'>('preview')
const mobile = ref(false), history = ref(false), help = ref(false), error = ref(''), toast = ref(''), creating = ref(false)
const selectedFile = ref<string>('index.html'), files = ref<Files>({})
const preview = ref(''), token = ref(''), frame = ref<HTMLIFrameElement | null>(null), runtimeError = ref(''), stopped = ref(false)
const selectedVersion = ref<string | null>(null), saving = ref(false)
const chatMessages=ref<HTMLElement|null>(null)
watch(()=>project.value?.messages.length,async()=>{await nextTick();if(chatMessages.value)chatMessages.value.scrollTop=chatMessages.value.scrollHeight})
let events: EventSource | null = null, poll: ReturnType<typeof setInterval> | null = null, toastTimer: ReturnType<typeof setTimeout> | null = null
let loadSequence = 0, disposed = false
const stages = [{key:'QUEUED',label:'准备任务'},{key:'PLANNING',label:'整理需求与计划'},{key:'GENERATING',label:'编写应用代码'},{key:'VALIDATING',label:'校验文件与语法'}]
const active = computed(() => !!project.value?.run && !['SUCCEEDED','FAILED'].includes(project.value.run.status))
const busy = computed(() => active.value || creating.value || saving.value)
const dirty = computed(() => { const v=project.value?.versions.find(v=>v.id===selectedVersion.value); return !!v && JSON.stringify(v.files)!==JSON.stringify(files.value) })
const sourceNames=computed(()=>Object.keys(files.value).sort())
const browserPreview=computed(()=>canPreview(files.value))
const fileLanguage=computed(()=>({java:'Java',xml:'XML',yml:'YAML',yaml:'YAML',js:'JavaScript',ts:'TypeScript',py:'Python',go:'Go',md:'Markdown',json:'JSON',sql:'SQL',css:'CSS',html:'HTML',properties:'Properties'}[selectedFile.value.split('.').pop()||'']||'Text'))
function loadFiles(version:Version){files.value={...version.files};if(!(selectedFile.value in files.value))selectedFile.value=sourceNames.value.find(n=>n.endsWith('.java'))||sourceNames.value[0]||'';runPreview()}
function beforeExport(e:MouseEvent){if(dirty.value){e.preventDefault();error.value='当前编辑尚未保存，请先保存，再导出源码。'}}
const visibleProjects = computed(()=>projects.value.filter(p=>p.title.toLowerCase().includes(search.value.toLowerCase())))
const suggestions = [{title:'个人记账工具',desc:'把每一笔生活，都记录下来',kind:'expense',prompt:'帮我做一个简洁好看的个人记账工具，可以新增和删除支出，显示总金额。'}, {title:'每日任务看板',desc:'让重要的事情，井井有条',kind:'tasks',prompt:'创建一个每日任务看板，可以添加任务、标记完成和删除任务，显示完成数量。'}, {title:'创意工作室官网',desc:'给你的灵感，一个漂亮的家',kind:'studio',prompt:'设计一个简洁有质感的创意工作室落地页，包含品牌介绍、服务和行动按钮。'}]
function notify(text:string){toast.value=text;if(toastTimer)clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',3500)}
function report(e:unknown){error.value=e instanceof Error?e.message:'操作失败，请重试'}
function disconnect(){events?.close();events=null;if(poll)clearInterval(poll);poll=null}
async function refreshList(){projects.value=await api<Project[]>('/projects')}
function runPreview(){runtimeError.value='';if(!browserPreview.value){preview.value='';stopped.value=false;if(selectedVersion.value&&view.value==='preview')view.value='code';return}try{token.value=randomId();preview.value=previewDocument(files.value,token.value);stopped.value=false}catch(e){runtimeError.value=e instanceof Error?e.message:'预览失败'}}
function chooseVersion(v:Version){if(dirty.value&&!window.confirm('当前代码尚未保存，切换版本会放弃修改。继续吗？'))return;selectedVersion.value=v.id;loadFiles(v)}
async function openProject(id:string, force=false){
 if(!force&&dirty.value&&!window.confirm('当前代码尚未保存，切换项目会放弃修改。继续吗？'))return
 const seq=++loadSequence;disconnect();error.value=''
 try {const detail=await api<Detail>('/projects/'+id);if(seq!==loadSequence||disposed)return;project.value=detail;if(mode.value==='image')view.value='images';localStorage.setItem('atoms-current',id);const v=detail.versions.find(v=>v.id===detail.currentVersion);if(v){selectedVersion.value=v.id;loadFiles(v)}else{selectedVersion.value=null;preview.value='';files.value={}}if(active.value&&detail.run)watchRun(detail.run.id,id)}catch(e){report(e)}
}
function home(){if(dirty.value&&!window.confirm('代码尚未保存，返回首页会放弃修改。继续吗？'))return;++loadSequence;disconnect();project.value=null;localStorage.removeItem('atoms-current');prompt.value='';error.value=''}
async function submit(){
 if(!prompt.value.trim()||busy.value)return
 if(!connected.value){error.value='后端尚未连接，请先启动 Java 服务';return}
 if(dirty.value){error.value='请先保存代码修改，再发起生成';return}
 creating.value=true;error.value=''
 try{let id=project.value?.id;if(!id){const p=await api<Project>('/projects','POST',{title:prompt.value.trim().slice(0,28)});id=p.id;await openProject(id,true);await refreshList()}
 const text=prompt.value.trim();const run=await api<Run>(`/projects/${id}/runs`,'POST',{prompt:text,baseVersion:project.value?.currentVersion??null,mode:mode.value,model:selectedModel.value});prompt.value='';
 if(project.value?.id===id){project.value.messages.push({id:randomId(),role:'user',content:text,mode:mode.value,model:selectedModel.value,createdAt:new Date().toISOString()});project.value.run=run;watchRun(run.id,id)}
 }catch(e){report(e)}finally{creating.value=false}
}
function watchRun(rid:string,pid:string){
 disconnect();let finishing=false
 async function receive(run:Run){if(project.value?.id!==pid||disposed)return;project.value.run=run;if(['SUCCEEDED','FAILED'].includes(run.status)&&!finishing){finishing=true;disconnect();await openProject(pid,true);if(run.status==='FAILED')error.value=run.error||'任务失败';if(run.mode==='image'&&run.status==='SUCCEEDED')view.value='images';await refreshList()}}
 events=new EventSource(`/api/runs/${rid}/events`);events.addEventListener('status',event=>{void receive(JSON.parse((event as MessageEvent).data))});
 // Polling is also the recovery path when a proxy buffers SSE or the connection drops.
 poll=setInterval(async()=>{try{await receive(await api<Run>('/runs/'+rid))}catch(e){report(e)}},2500)
}
async function save(){if(!project.value||busy.value)return;saving.value=true;error.value='';try{await api(`/projects/${project.value.id}/versions`,'POST',{files:files.value,baseVersion:project.value.currentVersion});await openProject(project.value.id,true);await refreshList();notify('已保存为新版本')}catch(e){report(e)}finally{saving.value=false}}
async function restore(v:Version){if(!project.value||busy.value)return;if(dirty.value&&!window.confirm('恢复版本会放弃尚未保存的编辑，继续吗？'))return;saving.value=true;try{await api(`/projects/${project.value.id}/restore`,'POST',{versionId:v.id,baseVersion:project.value.currentVersion});await openProject(project.value.id,true);await refreshList();history.value=false;notify('已恢复，并创建新版本')}catch(e){report(e)}finally{saving.value=false}}
async function copyCode(){try{await navigator.clipboard.writeText(files.value[selectedFile.value]||'');notify('代码已复制')}catch{notify('复制失败，请手动选择代码')}}
function example(text:string){selectMode('build');prompt.value=text}
function onPreviewMessage(e:MessageEvent){if(e.source===frame.value?.contentWindow&&e.data?.type==='preview-error'&&e.data.token===token.value&&typeof e.data.message==='string')runtimeError.value=e.data.message.slice(0,500)}
function shortcut(e:KeyboardEvent){if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='n'){e.preventDefault();home()}}
function beforeUnload(e:BeforeUnloadEvent){if(dirty.value){e.preventDefault();e.returnValue=''}}
onMounted(async()=>{window.addEventListener('keydown',shortcut);window.addEventListener('message',onPreviewMessage);window.addEventListener('beforeunload',beforeUnload);try{config.value=await api<ModelConfig>('/config');const savedMode=localStorage.getItem('atoms-mode');selectMode(savedMode==='chat'||savedMode==='image'?savedMode:'build');connected.value=true;await refreshList();const id=localStorage.getItem('atoms-current');if(id&&projects.value.some(p=>p.id===id))await openProject(id,true)}catch(e){report(e)}})
onUnmounted(()=>{window.removeEventListener('keydown',shortcut);disposed=true;disconnect();if(toastTimer)clearTimeout(toastTimer);window.removeEventListener('message',onPreviewMessage);window.removeEventListener('beforeunload',beforeUnload)})
</script>

<template>
<div class="app-shell" :class="{'sidebar-hidden':!sidebar,'is-workspace':!!project}">
 <aside class="sidebar" v-if="sidebar">
  <div class="brand-row"><button class="brand" @click="home" aria-label="Atoms 首页"><span class="brand-mark" aria-hidden="true"><i></i><i></i><i></i><i></i></span><span>Atoms</span></button><button class="icon-button subtle" @click="sidebar=false" aria-label="收起侧栏"><PanelLeftClose :size="17"/></button></div>
  <button class="new-project" @click="home"><Plus :size="17"/> 新建项目 <span class="shortcut"><Command :size="10"/> N</span></button>
  <label class="search"><Search :size="15"/><input v-model="search" placeholder="搜索项目" aria-label="搜索项目"/><span>⌕</span></label>
  <div class="nav-label">你的项目 <span>{{projects.length}}</span></div>
  <nav class="project-list"><button v-for="p in visibleProjects" :key="p.id" :class="{selected:project?.id===p.id}" @click="openProject(p.id)"><MessageSquare :size="16"/><span>{{p.title}}</span></button><div v-if="!visibleProjects.length" class="no-projects">{{search?'没有找到相关项目':'你的下一个想法，从这里开始。'}}</div></nav>
  <div class="sidebar-bottom"><div class="workspace-note"><span class="tiny-orbit">✧</span><strong>让好想法，真正发生。</strong><p>从第一行需求，到你的下一个作品。</p><button @click="help=true">探索工作台 <ArrowUpRight :size="13"/></button></div><button class="account" @click="help=true"><span class="avatar">Y</span><span><strong>我的工作空间</strong><small>{{config.demo?'本地演示模式':'AI 创作工作台'}}</small></span><Settings2 :size="16"/></button></div>
 </aside>
 <main class="main-area">
  <header class="topbar">
   <div v-if="!project" class="breadcrumbs"><button v-if="!sidebar" class="icon-button" @click="sidebar=true" aria-label="展开侧栏"><PanelLeftOpen :size="18"/></button><span class="top-label">我的工作空间</span></div>
   <div v-else class="breadcrumbs"><button v-if="!sidebar" class="icon-button" @click="sidebar=true" aria-label="展开侧栏"><PanelLeftOpen :size="18"/></button><button class="icon-button" @click="home" aria-label="返回首页"><ArrowLeft :size="16"/></button><span class="project-title">{{project.title}}</span><ChevronDown :size="13"/></div>
   <div class="top-actions"><span class="mode-indicator" :class="{offline:!connected}"><i></i>{{!connected?'服务未连接':config.demo?'演示模式':'模型已配置'}}</span><button v-if="project" class="button small" :disabled="!project.currentVersion" @click="history=true"><History :size="14"/> 版本历史</button><a v-if="project?.currentVersion" class="button small primary" :href="`/api/projects/${project.id}/export${selectedVersion ? '?versionId='+encodeURIComponent(selectedVersion) : ''}`" @click="beforeExport"><Download :size="14"/> 导出源码</a><button v-if="!project" class="button small nav-guide" @click="help=true">开始探索 <ArrowUpRight :size="14"/></button></div>
  </header>
  <div v-if="!project" class="home-scroll">
   <section class="hero">
    <div class="dashboard-notice"><Sparkles :size="13"/><span>一个工作空间，三种创造方式</span></div>
    <div class="creation-orbs" aria-label="创作方式"><button :disabled="busy" :class="{active:mode==='build'}" @click="selectMode('build')" aria-label="切换到构建应用" title="构建应用"><Code2 :size="23"/></button><button :disabled="busy" :class="{active:mode==='chat'}" @click="selectMode('chat')" aria-label="切换到对话问答" title="对话问答"><MessageSquare :size="22"/></button><button :disabled="busy" :class="{active:mode==='image'}" @click="selectMode('image')" aria-label="切换到图像生成" title="图像生成"><ImageIcon :size="23"/></button></div>
    <h1>你想创造什么？</h1>
    <p class="hero-description">构建应用、探索问题，或让想象变成画面。</p>
    <form class="prompt-box" @submit.prevent="submit"><textarea v-model="prompt" aria-label="描述你的应用想法" :placeholder="placeholder" maxlength="10000" @keydown.meta.enter.prevent="submit" @keydown.ctrl.enter.prevent="submit"></textarea><div class="prompt-bottom"><ModeControls :mode="mode" :model="selectedModel" :config="config" :disabled="busy" @mode="selectMode" @model="selectModel"/><button class="start-button" :aria-label="mode==='chat'?'发送问题':mode==='image'?'生成图片':'开始构建'" :disabled="!prompt.trim()||busy||!connected"><span>{{creating?'准备中':mode==='chat'?'发送问题':mode==='image'?'生成图片':'开始'}}</span><LoaderCircle v-if="creating" class="spin" :size="17"/><ArrowUp v-else :size="18"/></button></div></form>
    <div class="quick-ideas"><span>试试这些想法</span><button @click="example(suggestions[0].prompt)">✧ 个人记账</button><button @click="example(suggestions[1].prompt)">☷ 任务看板</button><button @click="example(suggestions[2].prompt)">◈ 品牌官网</button></div>
    <div v-if="error" class="error-banner"><CircleAlert :size="15"/>{{error}}<button @click="error=''" aria-label="关闭错误"><X :size="14"/></button></div>
   </section>
   <section id="inspiration" class="inspiration"><div class="section-heading"><div><span class="section-kicker">START CREATING</span><h2>从这些想法开始</h2></div><span class="section-caption">选择一个模板，开始你的创作 <ArrowUpRight :size="14"/></span></div>
    <div class="template-grid"><button v-for="s in suggestions" :key="s.kind" class="template-card" @click="example(s.prompt)"><div class="template-art" :class="s.kind"><div class="mini-browser"><div class="mini-header"><span class="mini-logo">{{s.kind==='expense'?'◈ pocket':s.kind==='tasks'?'◈ focus':'◈ studio.'}}</span><span>About &nbsp; Explore &nbsp; <b>Get started ↗</b></span></div><template v-if="s.kind==='expense'"><div class="mini-eyebrow">YOUR DAILY FINANCES</div><h3>小账本，大生活。</h3><div class="mini-stat-row"><div><small>本月支出</small><strong>¥ 2,480<span>.00</span></strong><em>↘ 比上月减少 12.8%</em></div><div class="mini-chart"><i v-for="n in 8" :key="n" :style="{height:(20+(n*17)%55)+'px'}"></i></div></div><div class="mini-list"><span>☕ 咖啡与小确幸</span><b>− ¥ 28.00</b></div><div class="mini-list"><span>◧ 日常生活</span><b>− ¥ 128.00</b></div></template><template v-else-if="s.kind==='tasks'"><div class="mini-eyebrow">A LITTLE FOCUS GOES A LONG WAY</div><h3>今天，好好专注。</h3><div class="mini-task"><span>○</span> 让下一个想法落地 <b>进行中</b></div><div class="mini-task"><span>○</span> 读一本喜欢的书 <b>今天</b></div><div class="mini-task done"><span>●</span> 给自己泡一杯咖啡 <Check :size="11"/></div><div class="mini-progress"><i></i></div><small class="mini-foot">一点一滴，都算数。</small></template><template v-else><div class="studio-orbit"></div><div class="mini-eyebrow">INDEPENDENT CREATIVE STUDIO</div><h3>Ideas made<br><i>extraordinary.</i></h3><p>We turn your what-ifs into what's next.</p><div class="mini-studio-button">Let's create together ↗</div></template></div></div><div class="template-info"><div><h3>{{s.title}}</h3><p>{{s.desc}}</p></div><span class="template-arrow"><ArrowUpRight :size="18"/></span></div></button></div>
   </section>
   <footer class="home-footer"><span class="footer-brand">✧ atoms</span><span>为尚未实现的想法而造。</span><span>把想法变成现实</span></footer>
  </div>
  <div v-else class="workbench">
   <section class="chat-panel"><div class="chat-heading"><span><Sparkles :size="15"/> 与 Atoms 一起创造</span><span class="live-dot"></span></div><div ref="chatMessages" class="chat-messages"><div class="chat-intro"><div class="assistant-avatar"><Sparkles :size="18"/></div><h3>从这里，开始创造。</h3><p>描述你的需求，我会把它变成可交互的应用。你也可以随时提出修改。</p></div><div v-for="m in project.messages" :key="m.id" class="message" :class="m.role"><div v-if="m.role==='assistant'" class="message-name"><span class="assistant-avatar tiny"><Sparkles :size="11"/></span>Atoms <span>{{m.model || modeLabels[m.mode || 'build']}}</span></div><p>{{m.content}}</p><div v-if="m.imageUrl" class="message-image"><button @click="view='images'"><img :src="m.imageUrl" alt="根据需求生成的图片" loading="lazy"/></button><a :href="m.imageUrl" download="atoms-image.png">下载原图 <Download :size="12"/></a></div></div><div v-if="active" class="generation-card"><div class="generation-title"><LoaderCircle class="spin" :size="16"/>{{project.run?.status==='ANSWERING'?'正在思考并回答':project.run?.status==='IMAGING'?'正在生成图片':project.run?.status==='REPAIRING'?'正在修复校验问题':'正在构建你的想法'}}</div><div v-for="(s,i) in (project.run?.mode==='build'?stages:[])" :key="s.key" class="generation-step" :class="{current:project.run?.status===s.key}"><Check v-if="stages.findIndex(x=>x.key===project?.run?.status)>i" :size="13"/><LoaderCircle v-else-if="project.run?.status===s.key" class="spin" :size="13"/><span v-else class="step-dot"></span>{{s.label}}</div><p v-if="project.run?.plan" class="plan-text">{{project.run.plan}}</p></div><div v-if="error" class="error-banner"><CircleAlert :size="14"/>{{error}}</div></div>
    <form class="chat-composer" @submit.prevent="submit"><textarea v-model="prompt" :disabled="busy" aria-label="提出修改需求" :placeholder="placeholder" @keydown.meta.enter.prevent="submit" @keydown.ctrl.enter.prevent="submit" maxlength="10000"></textarea><div class="composer-foot"><ModeControls :mode="mode" :model="selectedModel" :config="config" :disabled="busy" @mode="selectMode" @model="selectModel"/><button class="send-button" :disabled="busy||!prompt.trim()" aria-label="发送需求"><LoaderCircle v-if="busy" class="spin" :size="17"/><ArrowUp v-else :size="18"/></button></div></form><div class="chat-disclaimer">{{config.demo?'演示模式 · 未调用真实模型':mode==='image'?'图片单独计费 · 每次生成一张':mode==='chat'?'对话不会修改代码或创建版本':'AI 可能出错，请在预览中验证实际功能'}}</div>
   </section>
   <section class="output-panel"><div class="preview-toolbar"><div class="view-switch"><button :class="{active:view==='preview'}" @click="view='preview'"><Eye :size="14"/>预览</button><button :class="{active:view==='images'}" @click="view='images'"><ImageIcon :size="14"/>图片</button><button :class="{active:view==='code'}" @click="view='code'"><Code2 :size="14"/>代码</button></div><div class="preview-tools"><span v-if="selectedVersion" class="version-badge" @click="history=true">v{{project.versions.find(v=>v.id===selectedVersion)?.number}}<span v-if="dirty"> · 未保存</span></span><template v-if="view==='preview'"><button class="icon-button" :class="{chosen:!mobile}" @click="mobile=false" aria-label="桌面预览"><Monitor :size="16"/></button><button class="icon-button" :class="{chosen:mobile}" @click="mobile=true" aria-label="手机预览"><Smartphone :size="16"/></button><span class="tool-divider"></span><button class="icon-button" @click="runPreview" :disabled="!selectedVersion||!browserPreview" aria-label="重新运行预览"><RotateCcw :size="15"/></button><button class="icon-button" @click="stopped=true" :disabled="!preview||stopped||!browserPreview" aria-label="停止预览"><Square :size="13"/></button></template><template v-else-if="view==='code'"><span v-if="selectedVersion&&!browserPreview" class="source-only-label">源码工程</span><button v-if="browserPreview" class="button small" @click="runPreview();view='preview'" :disabled="!selectedVersion"><Play :size="13"/>运行</button><button class="button small primary" @click="save" :disabled="busy||!dirty"><CheckCheck :size="13"/>保存</button></template></div></div>
    <div v-if="view==='preview'" class="preview-area"><div class="preview-address" v-if="selectedVersion"><div class="browser-dots"><i></i><i></i><i></i></div><span><Globe :size="11"/>{{project.title}} <span class="address-muted">/ 预览</span></span><span class="isolated-badge">隔离运行</span></div><div class="iframe-shell" :class="{mobile}"><iframe v-if="preview&&!stopped" ref="frame" :srcdoc="preview" sandbox="allow-scripts allow-forms" title="生成应用预览" referrerpolicy="no-referrer"></iframe><div v-else class="preview-empty"><div class="empty-orbit"><Sparkles :size="28"/></div><h2>{{selectedVersion&&!browserPreview?'源码工程已就绪':stopped?'预览已停止':'你的作品，即将在这里诞生'}}</h2><p>{{selectedVersion&&!browserPreview?'此工程需要在本地编译或启动。请查看源码文件，或点击右上角导出源码。':stopped?'点击重新运行，继续体验你的应用。':'在左侧选择构建生成应用；也可以切换对话问答或图像生成。'}}</p><button v-if="selectedVersion&&!browserPreview" class="button" @click="view='code'"><Code2 :size="14"/>查看源码</button><span v-if="active" class="building-pill"><LoaderCircle class="spin" :size="13"/> 正在构建中…</span><button v-if="stopped" class="button" @click="runPreview"><Play :size="13"/>重新运行</button></div></div></div>
    <div v-else-if="view==='images'" class="image-gallery"><div class="gallery-heading"><span class="section-kicker">YOUR IMAGE COLLECTION</span><h2>让灵感，有画面。</h2><p>生成的图片保存在当前项目中，刷新后仍可查看和下载。</p></div><div v-if="!generatedImages.length" class="gallery-empty"><ImageIcon :size="35"/><h3>还没有图片</h3><p>选择“图像生成”，描述你想要的画面。</p><button class="button primary" @click="selectMode('image')">开始生成图片</button></div><div v-else class="gallery-grid"><article v-for="m in generatedImages.slice().reverse()" :key="m.id" class="generated-image-card"><img :src="m.imageUrl!" alt="生成图片" loading="lazy"/><div><strong>{{m.model}}</strong><small>{{new Date(m.createdAt).toLocaleString('zh-CN')}}</small><a class="button small" :href="m.imageUrl!" download="atoms-image.png"><Download :size="13"/>下载原图</a></div></article></div></div>
    <div v-else class="code-area"><div v-if="sourceNames.length>3" class="source-file-picker"><FolderOpen :size="14"/><select v-model="selectedFile" aria-label="选择源码文件"><option v-for="name in sourceNames" :key="name" :value="name">{{name}}</option></select><span>{{sourceNames.length}} 个文件</span></div><div class="file-tabs"><button v-for="name in sourceNames" :key="name" :title="name" :class="{selected:selectedFile===name}" @click="selectedFile=name"><FileCode2 :size="13"/>{{name}}<span v-if="selectedFile===name" class="file-dot"></span></button><button class="copy-code" @click="copyCode" aria-label="复制当前文件"><Copy :size="14"/></button></div><div class="editor"><div class="line-numbers" aria-hidden="true"><div v-for="n in (files[selectedFile]||'').split('\n').length" :key="n">{{n}}</div></div><textarea v-model="files[selectedFile]" :disabled="busy||!selectedVersion" spellcheck="false" :aria-label="`编辑 ${selectedFile}`"></textarea></div><div class="code-status"><span>{{fileLanguage}}</span><span>UTF-8 · {{(files[selectedFile]||'').length}} characters</span></div></div>
    <div v-if="runtimeError" class="runtime-error"><CircleAlert :size="15"/><span>{{runtimeError}}</span><button @click="example('修复以下预览运行错误：'+runtimeError)" :disabled="busy">请求修复</button><button class="icon-button" @click="runtimeError=''" aria-label="关闭预览错误"><X :size="13"/></button></div><div class="output-footer"><span><span class="status-dot"></span>{{active?'构建中':selectedVersion?'已加载保存版本':'准备就绪'}}</span><span>{{config.demo?'Demo workspace':'AI workspace'}} <span>✧</span></span></div>
   </section>
  </div>
 </main>
 <div v-if="history" class="modal-backdrop" @click.self="history=false"><section class="modal version-modal" role="dialog" aria-modal="true" aria-labelledby="history-title"><div class="modal-heading"><div><span class="section-kicker">YOUR CREATIVE JOURNEY</span><h2 id="history-title">版本历史</h2></div><button class="icon-button" @click="history=false" aria-label="关闭版本历史"><X :size="20"/></button></div><p class="modal-description">每一步创造，都有迹可循。恢复会创建一个新版本。</p><div class="version-list"><div v-for="v in project?.versions" :key="v.id" class="version-item"><div class="version-icon"><History :size="17"/></div><div class="version-details"><strong>版本 {{v.number}}<span v-if="v.id===project?.currentVersion">当前版本</span></strong><p>{{v.summary}}</p><small>{{new Date(v.createdAt).toLocaleString('zh-CN')}}</small></div><div class="version-actions"><button class="button small" @click="chooseVersion(v);history=false">查看</button><button class="button small primary" v-if="v.id!==project?.currentVersion" :disabled="busy" @click="restore(v)">恢复</button></div></div></div></section></div>
 <div v-if="help" class="modal-backdrop" @click.self="help=false"><section class="modal help-modal" role="dialog" aria-modal="true" aria-labelledby="help-title"><div class="modal-heading"><h2 id="help-title">让你的想法，开始发生。</h2><button class="icon-button" @click="help=false" aria-label="关闭指南"><X :size="20"/></button></div><div class="help-step"><span>01</span><div><h3>描述你想构建什么</h3><p>说清楚应用用途、主要交互和喜欢的风格。</p></div></div><div class="help-step"><span>02</span><div><h3>预览，再继续打磨</h3><p>实际操作应用，也可以在代码标签里编辑并保存。</p></div></div><div class="help-step"><span>03</span><div><h3>每个版本，都属于你</h3><p>随时恢复历史版本，或导出三个源码文件。</p></div></div><div class="help-mode"><CircleAlert :size="16"/><p>{{config.demo?'当前为离线演示。问答和图片均为示例，配置真实模型后即可正式使用。':'输入框下方可以切换构建、对话与图像模式，并选择对应模型。对话和生图不修改应用版本。图片单独计费，生成后保存到项目。'}}<br>工作台项目保存于服务端，使用当前浏览器匿名会话访问。</p></div><button class="button primary help-start" @click="help=false">开始创造 <ArrowUpRight :size="15"/></button></section></div>
 <Transition name="toast"><div v-if="toast" class="toast-message"><Check :size="16"/>{{toast}}</div></Transition>
</div>
</template>
